implementation_context.chunk_text:
def chunk_text(text: str, max_words: int = 80) -> list[str]:
    words = text.split()
    if not words:
        return []
    return [
        " ".join(words[i:i + max_words]).strip()
        for i in range(0, len(words), max_words)
        if " ".join(words[i:i + max_words]).strip()
    ]

